{
  "name": "minoemem",
  "version": "1.0.2",
  "description": "Persistent memory using Memvid, compatible with Claude Code (claude-brain)",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    ".opencode",
    "opencodeBrain-banner.png"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "persistent-memory",
    "memvid",
    "claude-brain",
    "ai-memory",
    "context-persistence",
    "ai-assistant",
    "code-memory",
    "session-persistence"
  ],
  "author": "deiviuds",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/deiviuds/opencode-brain"
  },
  "bugs": {
    "url": "https://github.com/deiviuds/opencode-brain/issues"
  },
  "homepage": "https://github.com/deiviuds/opencode-brain#readme",
  "dependencies": {
    "@memvid/sdk": "^2.0.155",
    "proper-lockfile": "^4.1.2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.51",
    "@opencode-ai/sdk": "^1.1.51",
    "@types/node": "^25.2.1",
    "@types/proper-lockfile": "^4.1.4",
    "tsup": "^8.5.1",
    "typescript": "^5.9.3",
    "vitest": "^4.0.18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.1.0"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "tool.execute.after",
      "chat.message",
      "session.idle"
    ]
  }
}
